type AuthProvider = "email" | "github" | "google" | "vercel";

type EnabledProviders = {
  email: boolean;
  github: boolean;
  google: boolean;
  vercel: boolean;
};

interface WindowWithEnv extends Window {
  ENV?: {
    NEXT_PUBLIC_AUTH_PROVIDERS?: string;
    NEXT_PUBLIC_GITHUB_CLIENT_ID?: string;
    NEXT_PUBLIC_GOOGLE_CLIENT_ID?: string;
    NEXT_PUBLIC_VERCEL_CLIENT_ID?: string;
  };
}

/**
 * Get the list of enabled authentication providers from environment variables
 * Defaults to email only if not specified
 */
export function getEnabledAuthProviders(): EnabledProviders {
  const providersEnv =
    process.env.NEXT_PUBLIC_AUTH_PROVIDERS ||
    (typeof window !== "undefined"
      ? (window as WindowWithEnv).ENV?.NEXT_PUBLIC_AUTH_PROVIDERS
      : undefined) ||
    "email";

  const enabledProviders = providersEnv
    .split(",")
    .map((p: string) => p.trim().toLowerCase());

  return {
    email: enabledProviders.includes("email"),
    github:
      enabledProviders.includes("github") &&
      !!(
        process.env.NEXT_PUBLIC_GITHUB_CLIENT_ID ||
        (typeof window !== "undefined" &&
          (window as WindowWithEnv).ENV?.NEXT_PUBLIC_GITHUB_CLIENT_ID)
      ),
    google:
      enabledProviders.includes("google") &&
      !!(
        process.env.NEXT_PUBLIC_GOOGLE_CLIENT_ID ||
        (typeof window !== "undefined" &&
          (window as WindowWithEnv).ENV?.NEXT_PUBLIC_GOOGLE_CLIENT_ID)
      ),
    vercel:
      enabledProviders.includes("vercel") &&
      !!(
        process.env.NEXT_PUBLIC_VERCEL_CLIENT_ID ||
        (typeof window !== "undefined" &&
          (window as WindowWithEnv).ENV?.NEXT_PUBLIC_VERCEL_CLIENT_ID)
      ),
  };
}

/**
 * Get array of enabled provider names
 */
export function getEnabledProvidersList(): AuthProvider[] {
  const providers = getEnabledAuthProviders();
  return Object.entries(providers)
    .filter(([, enabled]) => enabled)
    .map(([name]) => name as AuthProvider);
}

/**
 * Get the single enabled provider, or null if there are multiple
 */
export function getSingleProvider(): AuthProvider | null {
  const providersList = getEnabledProvidersList();
  return providersList.length === 1 ? providersList[0] : null;
}

import { betterAuth } from "better-auth";
import { drizzleAdapter } from "better-auth/adapters/drizzle";
import { anonymous, genericOAuth } from "better-auth/plugins";
import { eq } from "drizzle-orm";
import { isAiGatewayManagedKeysEnabled } from "./ai-gateway/config";
import { db } from "./db";
import {
  accounts,
  integrations,
  sessions,
  users,
  verifications,
  workflowExecutionLogs,
  workflowExecutions,
  workflowExecutionsRelations,
  workflows,
} from "./db/schema";

// Construct schema object for drizzle adapter
const schema = {
  user: users,
  session: sessions,
  account: accounts,
  verification: verifications,
  workflows,
  workflowExecutions,
  workflowExecutionLogs,
  workflowExecutionsRelations,
};

// Determine the base URL for authentication
// This supports Vercel Preview deployments with dynamic URLs
function getBaseURL() {
  // Priority 1: Explicit BETTER_AUTH_URL (set manually for production/dev)
  if (process.env.BETTER_AUTH_URL) {
    return process.env.BETTER_AUTH_URL;
  }

  // Priority 2: NEXT_PUBLIC_APP_URL
  if (process.env.NEXT_PUBLIC_APP_URL) {
    return process.env.NEXT_PUBLIC_APP_URL;
  }

  // Priority 3: Check if we're on Vercel (for preview deployments)
  if (process.env.VERCEL_URL) {
    // VERCEL_URL doesn't include protocol, so add it
    // Use https for Vercel deployments (both production and preview)
    return `https://${process.env.VERCEL_URL}`;
  }

  // Fallback: Local development
  return "http://localhost:3000";
}

// Build plugins array conditionally
const plugins = [
  anonymous({
    async onLinkAccount(data) {
      // When an anonymous user links to a real account, migrate their data
      const fromUserId = data.anonymousUser.user.id;
      const toUserId = data.newUser.user.id;

      console.log(
        `[Anonymous Migration] Migrating from user ${fromUserId} to ${toUserId}`
      );

      try {
        // Migrate workflows
        await db
          .update(workflows)
          .set({ userId: toUserId })
          .where(eq(workflows.userId, fromUserId));

        // Migrate workflow executions
        await db
          .update(workflowExecutions)
          .set({ userId: toUserId })
          .where(eq(workflowExecutions.userId, fromUserId));

        // Migrate integrations
        await db
          .update(integrations)
          .set({ userId: toUserId })
          .where(eq(integrations.userId, fromUserId));

        console.log(
          `[Anonymous Migration] Successfully migrated data from ${fromUserId} to ${toUserId}`
        );
      } catch (error) {
        console.error(
          "[Anonymous Migration] Error migrating user data:",
          error
        );
        throw error;
      }
    },
  }),
  ...(process.env.VERCEL_CLIENT_ID
    ? [
        genericOAuth({
          config: [
            {
              providerId: "vercel",
              clientId: process.env.VERCEL_CLIENT_ID,
              clientSecret: [REDACTED] || "",
              authorizationUrl: "https://vercel.com/oauth/authorize",
              tokenUrl: "https://api.vercel.com/login/oauth/token",
              userInfoUrl: "https://api.vercel.com/login/oauth/userinfo",
              // Include read-write:team scope when AI Gateway User Keys is enabled
              // This grants APIKey and APIKeyAiGateway permissions for creating user keys
              scopes: isAiGatewayManagedKeysEnabled()
                ? ["openid", "email", "profile", "read-write:team"]
                : ["openid", "email", "profile"],
              discoveryUrl: undefined,
              pkce: true,
              getUserInfo: async (tokens) => {
                const response = await fetch(
                  "https://api.vercel.com/login/oauth/userinfo",
                  {
                    headers: {
                      Authorization: `Bearer ${tokens.accessToken}`,
                    },
                  }
                );
                const profile = await response.json();
                console.log("[Vercel OAuth] userinfo response:", profile);
                return {
                  id: profile.sub,
                  email: profile.email,
                  name: profile.name ?? profile.preferred_username,
                  emailVerified: profile.email_verified ?? true,
                  image: profile.picture,
                };
              },
            },
          ],
        }),
      ]
    : []),
];

export const auth = betterAuth({
  baseURL: getBaseURL(),
  database: drizzleAdapter(db, {
    provider: "pg",
    schema,
  }),
  emailAndPassword: {
    enabled: true,
    requireEmailVerification: false,
  },
  socialProviders: {
    github: {
      clientId: process.env.GITHUB_CLIENT_ID || "",
      clientSecret: [REDACTED] || "",
      enabled: !!process.env.GITHUB_CLIENT_ID,
    },
    google: {
      clientId: process.env.GOOGLE_CLIENT_ID || "",
      clientSecret: [REDACTED] || "",
      enabled: !!process.env.GOOGLE_CLIENT_ID,
    },
  },
  plugins,
});

