const getProviderLabel = (provider: Provider) => {
  switch (provider) {
    case "vercel":
      return "Vercel";
    case "github":
      return "GitHub";
    case "google":
      return "Google";
    case "email":
      return "Email";
    default:
      return "Email";
  }
};

const getButtonText = (loading: boolean, mode: "signin" | "signup") => {
  if (loading) {
    return "Loading...";
  }
  return mode === "signup" ? "Sign Up" : "Sign In";
};

